command:
timeout 110 bash -c 'node --input-type=module -e '\''import fs from '\''"'\''"'\''node:fs'\''"'\''"'\'';
import crypto from '\''"'\''"'\''node:crypto'\''"'\''"'\'';
import assert from '\''"'\''"'\''node:assert/strict'\''"'\''"'\'';
import {countProject,countSource} from '\''"'\''"'\''./scripts/count-loc.mjs'\''"'\''"'\'';
const hash=x=>crypto.createHash('\''"'\''"'\''sha256'\''"'\''"'\'').update(x).digest('\''"'\''"'\''hex'\''"'\''"'\'');
const result=await countProject(process.cwd());
const counterSHA256=hash(fs.readFileSync('\''"'\''"'\''scripts/count-loc.mjs'\''"'\''"'\''));
assert.equal(counterSHA256,'\''"'\''"'\''f73b6acb7d073e90631936ad62be8705a9c2a2f93c7e2097e7ca4f5c062f12ab'\''"'\''"'\'');
for(const file of result.files){const source=fs.readFileSync(file.path);Object.assign(file,{bytes:source.length,sha256:hash(source),physical:source.toString().split('\''"'\''"'\''\n'\''"'\''"'\'').length-(source.at(-1)===10?1:0)});assert.ok(file.physical<=999,file.path);}
const original=Buffer.from("",'\''"'\''"'\''base64'\''"'\''"'\'').toString();
const current=fs.readFileSync('\''"'\''"'\''packages/web/src/pages/people/forms.jsx'\''"'\''"'\'','\''"'\''"'\''utf8'\''"'\''"'\'');
const formsBefore=countSource(original),formsAfter=countSource(current),delta=formsAfter-formsBefore;
console.log(JSON.stringify({counterSHA256,lockSHA256:hash(fs.readFileSync('\''"'\''"'\''package-lock.json'\''"'\''"'\'')),productionComparison:{before:result.total-delta,after:result.total,delta,formsBefore,formsAfter,method:'\''"'\''"'\''same frozen counter over final tree and initial forms content; exact SDK tree diff must establish all other production paths unchanged'\''"'\''"'\''},...result}));
'\'''

